import{_ as t,c as n,o as l,j as e,a as s}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"易圖通變卷三","description":"易圖通變 - 易圖通變卷三","frontmatter":{"title":"易圖通變卷三","description":"易圖通變 - 易圖通變卷三"},"headers":[],"relativePath":"classics/yitu-tongbian/004.md","filePath":"classics/yitu-tongbian/004.md"}'),i={name:"classics/yitu-tongbian/004.md"};function r(o,a,c,p,d,u){return l(),n("div",null,[...a[0]||(a[0]=[e("h1",{id:"易圖通變卷三",tabindex:"-1"},[s("易圖通變卷三 "),e("a",{class:"header-anchor",href:"#易圖通變卷三","aria-label":"Permalink to “易圖通變卷三”"},"​")],-1),e("p",null,"欽定四庫全書",-1),e("p",null,"宋雷思齊撰",-1),e("p",null,"道家以日月為易，始蹈常襲故，未始為然，卒究於大傳，則未始不然。曰：「乾坤，其易之蘊邪？乾坤成列，而易立乎其中矣。乾坤毀，則無以見易，易不可見，則乾坤或幾乎息矣。」是猶未識所見之易為何物也。則又曰：「乾坤，其易之門邪？乾，陽物也；坤，陰物也。陰陽合德而剛柔有體，以體天地之撰，以通神明之德。」是易之為物，有體可以見矣。則又曰：「闢戶謂之乾，闔戶謂之坤，一闔一闢謂之變，往來不窮謂之通。見乃謂之象，形乃謂之氣，制而用之謂之法，利用出入，民鹹用之謂之神。」是易之謂體者，又見其有用矣。故曰：「天地設位，而易行乎其中矣。」曰：「法象莫大乎天地，變通莫大乎四時，縣象著明莫大乎日月。」曰：「廣大配天地，變通配四時，陰陽之義配日月。」凡是數端，莫不舉日月以徵，則信其為易也完矣。夫易與天地準，能彌綸天地之道，仰觀象於天，俯觀法於地，則成象謂乾者，日也；效法謂坤者，月也。日象離，數極乎九，月象坎，數始乎一。凡九必對六，今雲一者，一合天五為六，坎一乾六為水生成，所以為月者也。且天地乃乾坤之體，乾坤乃天地之用。惟天地定位，而上下氣形有不易之分，故乾坤成列，而陰陽體用有變易之數。天地有常體而莫見其用，陰陽有常用而莫究其體。惟日月之體用兼著，故特著其義以配陰陽云爾。且明教以範圍天地而不過，曲成萬物而不遺者，特通乎晝夜之道而知也。夫晝夜之道，豈難知哉？百姓日用而不知爾。請略舉其凡。乾，陽物者，日其類也。坤，陰物者，月其類也。陰陽成列而合德者，四時合序，日月合明。闢戶謂乾，近則日之出旦，月之上弦，遠則春之日夜分，而謂「啟」也。闔戶謂坤，近則日之入夕，月之下弦，遠則秋之日，夜分而謂「閉」也。仰觀其成象，則日之晝，月之望，夏之景長而至。俯察其效法，則夜之分，月之朔，冬之景短而至也。是以日往則月來，月往則日來，日月相推而明生焉。寒往則暑來，暑往則寒來，寒暑相推而歲成焉。變化者，進退之象也。剛柔者，晝夜之象也。日月運行，一寒一暑。故曰：天地之道，貞觀者也。日月之道，貞明者也。天下之動，貞夫一者也。貞夫一也者，四時分至之中皆一也。而此特謂天下之動貞夫一，則正由坎之一也。一日之陽起，初動於夜分之際，固謂貞夫一也。一年之陽氣，復動於冬朔之始，尤見其貞夫一者也。坎之數一，離之數九，坎離以一九為乾，離為日，坎為月，日月必合於月之初一為朔。而日不雲朔，月乃雲朔，南不雲朔，北乃雲朔。夫朔，逆度也。逆與日會，故謂之朔。以朔文觀之，明著月之逆度者也。說卦曰：「易逆數也」。書亦曰：「平在朔易」，理實同也。由是以進乎日月之為易，其縣象得不謂著明矣乎？故月之三五而盈少陰陽之七八，三五而闕老陰陽之九六，總之以地數三十而月盡，又河圖法也。周天三百六十五度四分度之一，日每行一度，冬南夏北，為寒暑之中極。月行每十有三度而奇，與日之合者十有二朔，而歲常以備六陰六陽十有二月，天地節而四時成，是月之運行，勞亦甚矣。其稱坎為勞卦者，不徒謂水也。此坎之一數不入於參兩參伍之制，而特著其動之始也，中之始也。",-1),e("p",null,"合而言之，天地者體也，陰陽者用也。體者形所以用其氣，用者氣所以體其形。天以氣體其形，故其形下包乎地。地以形用其氣，故其氣上行乎天。是天之氣全體乎地之形，而地之形全用乎天之氣。此又參兩之製得以明之也。",-1),e("p",null,"一之始參，三之終參，皆天也，而並位乎平地之上。如乾者，老陽也，乃附於成數之六，陰位乎陰地，西北偏極乎退數之終。艮者，少陽也，乃附於成數之八，陰位乎陽地，東北偏，立乎進數之始。而特以坎中之一陽不在參兩之用者，因其始生自然之一介，然特立於陰陽終始之際，起歲之朔，月之朔，以體生生之謂易，斯足以明地之體全用乎天矣。一始之兩，二終之兩，皆地也，而兼列於平地之上。如巽，少陰也，雖以附地生數之四，陰，位乃在東南偏，陽氣升已過中之進數。坤，老陰也，雖以附地生數之二，陰，位猶在西南偏，陽氣降未及中之退數。且兼兩地並以奉中參天位之極，當天之極高，日之極中，斯足以明天之用全體乎地矣。以是知參兩之制，非有日以定其晝夜長短，有月以更其朔望贏縮，則天地之氣形體用，陰陽之變化生成，其升降進退之變通，分合出入之歸宿，則惡從而討其真是哉！",-1),e("p",null,"故嘗由是以參之，制數之元矣。天一之始，自北而中，而分地二於西南，不得謂「天地定位」者，陽正而下，陰偏而上也。二得名坤，一不得名乾者，一起於坎也。由一參二以為三，以前而東，蓋所以見人參於天地之中以生而動於震，因兩其二而四附以順而相入之巽，虛生其象以為四。然象非實體也，象天地與人極男女之相配以始者爾。一與三之陽，自然已各據其中，而二與四之未中，未有以正之，可遂已乎？故有待取用於成數之交合以成其正也。五雖虛位於中，而有其數可制其用。一交五而以其一相配而成六於乾，二交五而以其二相配而成七於兌，三交五而以其三相配而成八於艮，四交五而以其四相配而成九於離。然後始謂之成象。成象則謂之乾，而效法則謂之坤矣，乃得謂之「天地定位」也。其實一自合一，二自合二，三自合三，四自合四，特以交五而變爾。於是坎一之陽，合而成乾六之陰；坤二之陰，合而成兌七之陽；震三之陽，合而成艮八之陰；巽四之陰，合而成離九之陽。其始正者合而輔於偏，始偏者合而歸之正。於是八卦成列，而象在其中矣。亦惟一之自中，坎獨自若而不入於數，而河圖參天兩地，參伍錯綜之變，得以行乎其中也。故由參天之制皆用九，而知九為乾之用；由兩地之制皆用六，而知六為坤之用。蓋乾之始參於艮八而不足於數，則取震之一而九之。中參當陽極，而體數之全無餘，不足則自九之終參，則取兌過中有餘之三，以奉乾六之終而九之。兩之始起數於震中之二，以合巽四之不足而六之。兩之終起數於坤之本二，以合兌中有餘之四而六之。是明參兩九六所用之槩也。或有謂坤二與兌七而九，乾位自得六數，亦自成九六也。曾不識兩之制皆終地上，參之制皆終地下，又焉得而易之哉？況乾本九也，今數乃損而六；坤本六也，今數乃增之而九者，尤足以明老陰之六變而之九，老陽之九變而之六，而卦爻之所以成九六也。由參天之用必九，兩地之體必六。下系之首曰：「八卦成列，象在其中矣。因而重之，爻在其中矣。」而後世乃謂易畫之重非由羲始，吾不信也。",-1),e("p",null,"且說卦謂「說言乎兌，成言乎艮」，凡再言。其「山澤通氣」者，即鹹卦也。鹹之彖曰：二氣感應以相與，止而說，天地感而萬物化生，聖人感人心而天下和平。觀其所感，而天地萬物之情可見矣。其「雷風相薄」者，即恆卦也。恆之彖曰：「雷風相與，巽而動，天地之道，恆久而不已也。日月得天而能久照，四時變化而能久成，聖人久於其道，而天下化成。」觀其所恆，而天地萬物之情可見矣。溯求於下經之人道攸始，則說卦、重卦，其旨一毫不悖也。故愚謂重易斷自羲始，不然，禮謂三易其經卦皆八，其別皆六十四，其欺我哉！求易之道，試以是進之。說卦曰：「聖人之作易也，參天兩地而倚數，觀變於陰陽而立卦，發揮於剛柔而生爻。」因參稽其所以參兩者，其得於河圖無間然矣。且「帝出乎震」一章，尤河圖之大講明也。特截自震起於泰中，環周而訖於艮，寓夏正之歲更爾。故曰：「終萬物、始萬物者，莫盛乎艮。」曰：「艮東北之卦，萬物之所成終而所成始。」意蓋謂又始於出乎震者也。此實孔子特以變通四時言也，而於通乎晝夜之道而知，則未及悉也。夫兩之制，並起於平地以奉中參者，自春而秋，以分必極於夏之至者，亦晝之象也。始終之參，皆在地中者，自秋而春，以分必極於冬之至者，亦夜之象也。請以日用常行變而通之。則出乎震者，人之始作於旦也，古謂震旦，所以驗也。齊乎巽者，動而相與之交也。相見乎離，則交際之極也。致役乎坤，則動極徐靜也。說言乎兌，休且入也。自震至兌，此晝之體用，人所同見。至於戰乎乾，卒取終參之制，其數之九，則存兌餘之三，嚮晦入息於乾，六以終也。陰陽相薄，閉塞不用之時也。然終則有始，至於勞乎坎，則夜分之氣復動，準於七日之復則同也。成言乎艮，則遠接兌餘之三，說言乎兌也。山澤通氣，感而相與，雖止於其所，而時行則行，斯人事之又興始者也。變化者，進退之象也；剛柔者，晝夜之象也。吾見自羲文以來，河圖之一陰一陽，進退升降，往復循環，周流不息，開古訖今，遠之一歲之冬夏，邇之一日之晝夜，莫不由斯道也。吾日用常行，不在它求，參天之道自艮始者於是乎在。其視太玄以七百二十九贊之準易，皇極以元會運世之旁通，各以一期之歲月日時為數例，視今通其變、極其數，於河圖日可見之行也，豈不易簡而理得哉！斯非至精變而神者歟！易圖通變卷三。",-1)])])}const f=t(i,[["render",r]]);export{_ as __pageData,f as default};
